package packages;

public class Task_3 {
// odd numbers in range using for loop
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int start = 20, end = 40;
		for (int i = start; i <= end; i++) {
			if (i % 2 != 0) {
				System.out.println(i);
			}
		}
	}

}
